#!/usr/bin/env ruby
require'json';require'csv';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);archive=File.join(client,'development/archived-direct-game-folders');catalog=CSV.read(File.join(root,'server/Bootstrap/src/main/resources/game-catalog-528.tsv'),headers:true,col_sep:"\t").map(&:to_h);norm=->(s){s.downcase.gsub(/[^a-z0-9]/,'')};roots=Dir.glob(File.join(archive,'**/*')).select{|p|File.directory?(p)&&Dir.children(p).any?{|n|File.file?(File.join(p,n))}};rows=roots.map do|p|rel=p.delete_prefix(archive+'/');token=norm.call(rel);matches=catalog.select{|g|c=norm.call(g['code']);d=norm.call(g['displayName']);(!c.empty?&&token.include?(c))||(!d.empty?&&token.include?(d))};{archivePath:rel,files:Dir.glob(File.join(p,'*')).count{|f|File.file?(f)},matches:matches.map{|g|{gameId:g['gameId'],code:g['code'],category:g['category'],family:g['family']}}}end;unmapped=rows.select{|r|r[:matches].empty?};ambiguous=rows.select{|r|r[:matches].length>1};report={schemaVersion:1,leafAssetDirectories:rows.length,rows:rows,unmapped:unmapped.map{|r|r[:archivePath]},ambiguous:ambiguous.map{|r|r[:archivePath]},checks:{allMapped:unmapped.empty?,unambiguous:ambiguous.empty?},verdict:unmapped.empty?&&ambiguous.empty? ? 'passed':'blocked-incomplete-archive-map'};out=File.join(root,'docs/generated/carch02-direct-game-map.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CARCH02 AUDITED: #{rows.length} leaves, #{unmapped.length} unmapped, #{ambiguous.length} ambiguous"
